import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type MessageValidator = (message: Record<string, unknown>) => ValidationResult;

const messageValidators = new Map<string, MessageValidator>([
  ['user_message', validateUserMessage],
  ['ping', validatePingMessage],
  ['list_sessions', validateListSessionsMessage],
]);

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators.get(message.type);
  return validator === undefined ? {valid: false, error: `Unknown message type: ${message.type}`} : validator(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && !isValidListLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be an integer from 0 to 200'};
  }

  const listSessions: ListSessionsMessage = {
    type: 'list_sessions',
    limit: message.limit as number | undefined,
  };

  if (message.before === undefined) return {valid: true, data: listSessions};

  const before = validateListCursor(message.before);
  if (!before.valid) return before;
  listSessions.before = before.cursor;

  return {valid: true, data: listSessions};
}

function isValidListLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0 && limit <= 200;
}

function validateListCursor(value: unknown): ValidationFailure | {valid: true; cursor: ListSessionsMessage['before']} {
  if (typeof value !== 'object' || value === null) {
    return {valid: false, error: 'list_sessions before must be a cursor object'};
  }

  const cursor = value as Record<string, unknown>;
  if (!isValidSessionId(cursor.sessionId)) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }
  if (!isValidCursorDate(cursor.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
  }
  return {valid: true, cursor: {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId}};
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= 128;
}

function isValidCursorDate(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  const timestamp = typeof updatedAt === 'number' ? updatedAt : Date.parse(updatedAt);
  return Number.isFinite(timestamp);
}

